effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
// Matrizes de skew que o HLSLcc esperava do cbuffer VGlobals do Unity (que o conversor automático perdeu).
// Column-major (GLSL): coluna 0 = (1, shearY, 0, 0); coluna 1 = (shearX, 1, 0, 0); coluna 3 = translação (zero aqui,
// o pivô é tratado fora da matriz). O _prev é identidade — motion blur do skew exige o valor do quadro anterior,
// que o motor não guarda hoje; fica off (passthrough) pra esse lado até surgir `prevState`.
// Global do GLSL ES só aceita valor constante: a matriz é montada no começo do main (0.910.0).
mat4 hlslcc_mtx4x4_skew_mat;
mat4 hlslcc_mtx4x4_skew_mat_prev = mat4(1.0);

vec4 u_xlat0;
bvec2 u_xlatb0;
vec4 u_xlat1;
vec2 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
bool u_xlatb4;
vec4 u_xlat5;
vec2 u_xlat6;
vec2 u_xlat8;
bool u_xlatb12;
int u_xlati14;
bool u_xlatb16;
float u_xlat18;
int u_xlati18;
bool u_xlatb18;
int u_xlati20;
void main()
{
    hlslcc_mtx4x4_skew_mat = mat4(
    vec4(1.0, _skew_y, 0.0, 0.0),
    vec4(_skew_x, 1.0, 0.0, 0.0),
    vec4(0.0, 0.0, 1.0, 0.0),
    vec4(0.0, 0.0, 0.0, 1.0));
    u_xlat0.xy = acScreenNorm.xy + (-_skew_pivot.xy);
    u_xlat0.xy = u_xlat0.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat6.xy = u_xlat0.yy * hlslcc_mtx4x4_skew_mat[1].xy;
    u_xlat0.xy = hlslcc_mtx4x4_skew_mat[0].xy * u_xlat0.xx + u_xlat6.xy;
    u_xlat0.xy = u_xlat0.xy + hlslcc_mtx4x4_skew_mat[3].xy;
    u_xlat0.xy = u_xlat0.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat0.xy = u_xlat0.xy + _skew_pivot.xy;
    u_xlatb12 = int(_texture_wrap_mode)==2;
    if(u_xlatb12){
        u_xlat1 = texture(SourceTexMirror, u_xlat0.xy);
    } else {
        u_xlat1 = texture(inputImg, u_xlat0.xy);
    }
    u_xlatb18 = 0<int(_enable_motion_blur);
    if(u_xlatb18){
        u_xlat2.xy = acScreenNorm.xy + (-vec2(_skew_pivot_prev.x, _skew_pivot_prev.y));
        u_xlat2.xy = u_xlat2.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
        u_xlat8.xy = u_xlat2.yy * hlslcc_mtx4x4_skew_mat_prev[1].xy;
        u_xlat2.xy = hlslcc_mtx4x4_skew_mat_prev[0].xy * u_xlat2.xx + u_xlat8.xy;
        u_xlat2.xy = u_xlat2.xy + hlslcc_mtx4x4_skew_mat_prev[3].xy;
        u_xlat2.xy = u_xlat2.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
        u_xlat2.xy = u_xlat2.xy + vec2(_skew_pivot_prev.x, _skew_pivot_prev.y);
        u_xlat2.xy = u_xlat0.xy + (-u_xlat2.xy);
        u_xlat2.xy = u_xlat2.xy * vec2(_motion_amount);
        u_xlati18 = int(_motion_samples) + int(0xFFFFFFFFu);
        u_xlat18 = float(u_xlati18);
        u_xlat3 = u_xlat1;
        u_xlati14 = int(_texture_wrap_mode);
        for(int u_xlati_loop_1 = 1 ; u_xlati_loop_1<int(_motion_samples) ; u_xlati_loop_1++)
        {
            u_xlat4.x = float(u_xlati_loop_1);
            u_xlat4.x = u_xlat4.x / u_xlat18;
            u_xlat4.xy = (-u_xlat2.xy) * u_xlat4.xx + u_xlat0.xy;
            u_xlatb16 = u_xlati14==2;
            if(u_xlatb16){
                u_xlat5 = texture(SourceTexMirror, u_xlat4.xy);
            } else {
                u_xlat5 = texture(inputImg, u_xlat4.xy);
            }
            u_xlat3 = u_xlat3 + u_xlat5;
            u_xlat3.xyz = u_xlat1.xyz * vec3(vec3(_motion_stay, _motion_stay, _motion_stay)) + u_xlat3.xyz;
        }
        u_xlat18 = float(int(_motion_samples));
        u_xlat1 = u_xlat3 / vec4(u_xlat18);
    }
    u_xlatb2.xy = lessThan(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb0.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlatb0.x = u_xlatb0.x || u_xlatb2.x;
    u_xlatb0.x = u_xlatb2.y || u_xlatb0.x;
    u_xlatb0.x = u_xlatb0.y || u_xlatb0.x;
    u_xlat0.x = (u_xlatb0.x) ? 0.0 : 1.0;
    u_xlat0.x = (int(_texture_wrap_mode) != 0) ? 1.0 : u_xlat0.x;
    u_xlat1 = u_xlat0.xxxx * u_xlat1;
    if(u_xlatb12){
        u_xlat0 = texture(SourceTexMirror, acScreenNorm.xy);
    } else {
        u_xlat0 = texture(inputImg, acScreenNorm.xy);
    }
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
